import type { BankQuestion } from "@/lib/bank";

/** Bhakti and Sufi Movements (History): 115 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "history-bhakti-sufi-1", "question": "The Bhakti saint Kabir is traditionally regarded as a disciple of:", "options": ["Vallabhacharya", "Ramananda", "Chaitanya", "Ramanuja"], "answer": 1, "explanation": "Tradition makes Kabir a disciple of Ramananda of Varanasi. Vallabhacharya’s best-known follower was Surdas.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-2", "question": "Guru Nanak was born in 1469 at Talwandi, which is now known as:", "options": ["Kartarpur", "Anandpur Sahib", "Nankana Sahib", "Amritsar"], "answer": 2, "explanation": "Talwandi Rai Bhoi, near Lahore in present-day Pakistan, is now Nankana Sahib. Kartarpur, on the Ravi, is where Nanak spent his last years.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-bhakti-sufi-3", "question": "Mirabai, the Rajput princess and poet-saint, was a devotee of:", "options": ["Rama", "Shiva", "Durga", "Krishna"], "answer": 3, "explanation": "Mirabai of Merta, married into the Sisodia house of Mewar, composed bhajans to Krishna (Giridhar Gopal).", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-4", "question": "The dargah of Khwaja Moinuddin Chishti, who brought the Chishti order to India, is at:", "options": ["Ajmer", "Delhi", "Fatehpur Sikri", "Multan"], "answer": 0, "explanation": "Khwaja Moinuddin Chishti settled at Ajmer in the late 12th century and died there in 1236. Delhi has the dargah of Nizamuddin Auliya.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-bhakti-sufi-5", "question": "Tulsidas wrote the Ramcharitmanas in which language?", "options": ["Braj Bhasha", "Sanskrit", "Awadhi", "Maithili"], "answer": 2, "explanation": "The Ramcharitmanas is in Awadhi. Surdas wrote in Braj Bhasha, and Vidyapati in Maithili.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-bhakti-sufi-6", "question": "The devotional songs called abhangas, addressed to Vitthala of Pandharpur, are chiefly associated with:", "options": ["Surdas", "Tukaram", "Kabir", "Chaitanya"], "answer": 1, "explanation": "Tukaram, a 17th-century Marathi saint of the Varkari tradition, is famous for his abhangas to Vitthala.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-7", "question": "Who popularised congregational kirtan and Krishna devotion in Bengal in the early 16th century?", "options": ["Chaitanya Mahaprabhu", "Sankaradeva", "Vallabhacharya", "Ramananda"], "answer": 0, "explanation": "Chaitanya (1486–1534) of Nabadwip founded Gaudiya Vaishnavism and spread sankirtan. Sankaradeva worked in Assam.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-bhakti-sufi-8", "question": "The Nayanars of the Tamil region were devotees of:", "options": ["Vishnu", "Murugan", "Shiva", "The Buddha"], "answer": 2, "explanation": "The 63 Nayanars were Shaiva saints; the 12 Alvars were devotees of Vishnu.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-bhakti-sufi-9", "question": "The Virashaiva (Lingayat) movement of 12th-century Karnataka was led by:", "options": ["Basavanna", "Madhvacharya", "Purandaradasa", "Namdev"], "answer": 0, "explanation": "Basavanna, a minister at the court of the Kalachuri king Bijjala, led the Virashaiva movement and composed vachanas in Kannada.", "difficulty": "moderate", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-bhakti-sufi-10", "question": "In Sufi terminology, a “khanqah” was:", "options": ["A collection of a saint’s sayings", "The tomb of a Sufi saint", "A Sufi hospice where the master lived with disciples and received visitors", "A musical assembly"], "answer": 2, "explanation": "The khanqah was the hospice of a Sufi master (shaikh). The tomb is the dargah, and the musical assembly is sama.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-11", "question": "Amir Khusrau, the poet called Tuti-i-Hind, was a disciple of:", "options": ["Baba Farid", "Nizamuddin Auliya", "Moinuddin Chishti", "Bahauddin Zakariya"], "answer": 1, "explanation": "Amir Khusrau was the devoted disciple of the Chishti saint Nizamuddin Auliya of Delhi and is buried near him.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-bhakti-sufi-12", "question": "Sankaradeva, who spread Ekasarana Vaishnavism through namghars and sattras, worked in:", "options": ["Odisha", "Bengal", "Manipur", "Assam"], "answer": 3, "explanation": "Sankaradeva (15th–16th century) preached in Assam; the sattras (monasteries) and namghars (prayer halls) are his legacy.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-13", "question": "Sharafuddin Yahya Maneri of Bihar, famous for his letters (Maktubat), belonged to which Sufi order?", "options": ["Chishti", "Firdausi", "Suhrawardi", "Qadiri"], "answer": 1, "explanation": "Maneri was the leading saint of the Firdausi silsila, an offshoot of the Suhrawardi order, at Bihar Sharif.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-14", "question": "Shaikh Ahmad Sirhindi, who opposed Akbar’s religious policies and was called Mujaddid Alf-i-Sani, belonged to:", "options": ["The Chishti order", "The Suhrawardi order", "The Naqshbandi order", "The Firdausi order"], "answer": 2, "explanation": "Sirhindi was a disciple of Khwaja Baqi Billah, who brought the orthodox Naqshbandi order to India.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-15", "question": "The Gurmukhi script is traditionally said to have been developed and standardised by:", "options": ["Guru Nanak", "Guru Angad", "Guru Arjan", "Guru Gobind Singh"], "answer": 1, "explanation": "Guru Angad, the second Guru, is credited with standardising Gurmukhi, in which Sikh scripture is written.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-16", "question": "The city of Ramdaspur, later called Amritsar, was founded by:", "options": ["Guru Amar Das", "Guru Hargobind", "Guru Arjan", "Guru Ram Das"], "answer": 3, "explanation": "The fourth Guru, Ram Das, founded Ramdaspur around 1577; his successor Guru Arjan built the Harmandir Sahib there.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-17", "question": "The Pushti Marga, a path of devotion to Krishna based on divine grace, was founded by:", "options": ["Nimbarka", "Chaitanya", "Vallabhacharya", "Madhvacharya"], "answer": 2, "explanation": "Vallabhacharya founded the Pushti Marga and taught Shuddhadvaita; Surdas was among his disciples.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-18", "question": "In Sufi thought, “fana” means:", "options": ["The annihilation of the self in God", "A spiritual retreat of forty days", "The chain of succession of masters", "The renunciation of property"], "answer": 0, "explanation": "Fana is the passing away of the self in God. The forty-day retreat is chilla, and the chain of masters is the silsila.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-19", "question": "Lal Ded (Lalleshwari), whose sayings are called vakhs, was a mystic poet of:", "options": ["Kashmir", "Punjab", "Gujarat", "Assam"], "answer": 0, "explanation": "Lal Ded was a 14th-century Kashmiri Shaiva mystic; her vakhs are among the earliest works of Kashmiri literature.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-bhakti-sufi-20", "question": "Which Maharashtrian saint of Pandharpur has hymns included in the Guru Granth Sahib?", "options": ["Tukaram", "Jnaneshwar", "Eknath", "Namdev"], "answer": 3, "explanation": "Namdev’s compositions are included in the Guru Granth Sahib along with those of Kabir, Ravidas and Baba Farid.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-21", "question": "According to tradition, Mirabai regarded which saint as her guru?", "options": ["Kabir", "Ravidas", "Tulsidas", "Chaitanya"], "answer": 1, "explanation": "Tradition holds that Mirabai took Ravidas (Raidas), a leather-worker saint of Varanasi, as her guru.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-bhakti-sufi-22", "question": "The Periya Puranam, the hagiography of the 63 Nayanars, was composed by:", "options": ["Sekkizhar", "Nathamuni", "Kamban", "Appar"], "answer": 0, "explanation": "Sekkizhar wrote the Periya Puranam in the reign of the Chola king Kulottunga II. Nathamuni compiled the Alvar hymns, and Kamban wrote the Tamil Ramayana.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-23", "question": "Akka Mahadevi, whose vachanas in Kannada are addressed to Chennamallikarjuna, belonged to:", "options": ["The Varkari tradition", "The Virashaiva movement", "The Alvar tradition", "The Mahanubhav sect"], "answer": 1, "explanation": "Akka Mahadevi was a 12th-century Virashaiva saint, a contemporary of Basavanna.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-bhakti-sufi-24", "question": "The Chishti saint whose verses are included in the Guru Granth Sahib and whose shrine is at Pakpattan was:", "options": ["Nizamuddin Auliya", "Qutbuddin Bakhtiyar Kaki", "Baba Farid (Fariduddin Ganj-i-Shakar)", "Salim Chishti"], "answer": 2, "explanation": "Baba Farid (d. 1265), a Chishti master, composed Punjabi verses included in the Guru Granth Sahib; his dargah is at Pakpattan in Pakistan.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-25", "question": "Match the philosopher with his doctrine: A. Shankaracharya B. Ramanuja C. Madhvacharya D. Nimbarka — 1. Dvaita 2. Advaita 3. Dvaitadvaita 4. Vishishtadvaita", "options": ["A-2, B-1, C-4, D-3", "A-2, B-4, C-3, D-1", "A-2, B-4, C-1, D-3", "A-4, B-2, C-1, D-3"], "answer": 2, "explanation": "Shankara – Advaita (non-dualism); Ramanuja – Vishishtadvaita (qualified non-dualism); Madhva – Dvaita (dualism); Nimbarka – Dvaitadvaita (dualism-cum-non-dualism).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-26", "question": "Arrange these saints in chronological order: 1. Tulsidas 2. Ramanuja 3. Guru Nanak 4. Kabir", "options": ["2-4-3-1", "4-2-3-1", "2-3-4-1", "2-4-1-3"], "answer": 0, "explanation": "Ramanuja (11th–12th century), Kabir (15th century), Guru Nanak (1469–1539), Tulsidas (1532–1623).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-bhakti-sufi-27", "question": "Which pair of saint and region is NOT correctly matched?", "options": ["Narsinh Mehta – Gujarat", "Purandaradasa – Karnataka", "Tukaram – Gujarat", "Lal Ded – Kashmir"], "answer": 2, "explanation": "Tukaram belonged to Dehu in Maharashtra. Narsinh Mehta (author of “Vaishnav Jan To”) was Gujarati and Purandaradasa a Kannada Haridasa.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-28", "question": "How many of these statements about Kabir are correct? I. His verses include sakhis and pads. II. The Bijak is a compilation of his verses preserved by the Kabirpanth. III. He was a disciple of Vallabhacharya. IV. He composed his verses in classical Sanskrit.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II are correct. Kabir is linked to Ramananda, not Vallabhacharya, and he wrote in a vernacular mix of Hindi (sadhukkadi), not Sanskrit.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-29", "question": "How many of these statements about the Sufis are correct? I. The Chishtis generally kept their distance from the court. II. The Suhrawardis accepted state patronage and grants. III. The Chishtis practised sama, listening to music to attain ecstasy. IV. In a silsila, the master was the pir and the disciple the murid.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The Suhrawardis, unlike the Chishtis, accepted official posts and grants.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-30", "question": "Assertion (A): Kabir and Guru Nanak composed their teachings in the spoken languages of the people. Reason (R): They wanted their message to reach ordinary people who did not know Sanskrit or Persian.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: the Bhakti saints used vernaculars precisely so that common people could understand them.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-31", "question": "Assertion (A): Chishti saints used Hindavi and held sama gatherings. Reason (R): The Chishtis believed in accepting state patronage and holding court offices.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 2, "explanation": "A is true. R is false: the Chishtis kept away from the court and refused official posts; it was the Suhrawardis who accepted state patronage.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-32", "question": "Match the work with its author: A. Sursagar B. Jnaneshwari C. Bijak D. Ramcharitmanas — 1. Kabir 2. Tulsidas 3. Surdas 4. Jnaneshwar", "options": ["A-3, B-4, C-1, D-2", "A-3, B-1, C-4, D-2", "A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1"], "answer": 0, "explanation": "Sursagar – Surdas; Jnaneshwari, the Marathi commentary on the Gita – Jnaneshwar; Bijak – Kabir; Ramcharitmanas – Tulsidas.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-33", "question": "Arrange in chronological order: 1. Compilation of the Adi Granth 2. Founding of the Khalsa 3. Martyrdom of Guru Tegh Bahadur 4. Martyrdom of Guru Arjan", "options": ["1-3-4-2", "1-4-3-2", "4-1-3-2", "1-4-2-3"], "answer": 1, "explanation": "Adi Granth compiled by Guru Arjan in 1604; Guru Arjan executed in 1606; Guru Tegh Bahadur executed in 1675; Khalsa founded by Guru Gobind Singh in 1699.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-34", "question": "Who among the following is NOT traditionally counted among the disciples of Ramananda?", "options": ["Kabir", "Ravidas", "Sena", "Surdas"], "answer": 3, "explanation": "Tradition lists Kabir, Ravidas, Sena (a barber) and Dhanna among Ramananda’s disciples. Surdas was a follower of Vallabhacharya.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-35", "question": "How many of these statements are correct? I. The Alvars were devotees of Vishnu. II. Karaikkal Ammaiyar was an Alvar. III. The Tevaram contains the hymns of the Alvars. IV. The Nalayira Divya Prabandham was compiled by Ramanuja.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 0, "explanation": "Only I is correct. Karaikkal Ammaiyar was a Nayanar, the Tevaram holds Nayanar hymns (Appar, Sambandar, Sundarar), and the Nalayira Divya Prabandham was compiled by Nathamuni.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-36", "question": "Which pair of Sufi saint and the place of his dargah is NOT correctly matched?", "options": ["Moinuddin Chishti – Ajmer", "Nizamuddin Auliya – Delhi", "Bahauddin Zakariya – Gulbarga", "Salim Chishti – Fatehpur Sikri"], "answer": 2, "explanation": "Bahauddin Zakariya, who established the Suhrawardi order in India, is buried at Multan. Gulbarga has the dargah of Gesu Daraz (Bande Nawaz).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-37", "question": "Arrange these Sufi saints by the year of their death: 1. Shaikh Salim Chishti 2. Nizamuddin Auliya 3. Shaikh Ahmad Sirhindi 4. Moinuddin Chishti", "options": ["4-2-3-1", "2-4-1-3", "4-1-2-3", "4-2-1-3"], "answer": 3, "explanation": "Moinuddin Chishti 1236, Nizamuddin Auliya 1325, Salim Chishti 1572, Ahmad Sirhindi 1624.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-38", "question": "How many of these statements about Guru Nanak are correct? I. He was born in 1469. II. He set up a settlement at Kartarpur on the Ravi. III. He started the practice of the common kitchen (langar). IV. His hymns were compiled into the Adi Granth by Guru Gobind Singh.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The Adi Granth was compiled by Guru Arjan in 1604; Guru Gobind Singh later added Guru Tegh Bahadur’s hymns.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-bhakti-sufi-39", "question": "Assertion (A): The Lingayats challenged the idea of caste and questioned the theory of rebirth. Reason (R): Basavanna was a minister at the court of the Kalachuri king Bijjala.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 1, "explanation": "Both are true, but R does not explain A: Basavanna’s office at court is a biographical fact, while the Lingayat stand on caste came from their devotional teaching.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-40", "question": "Which one of the following is NOT counted among the Nirguna Bhakti saints?", "options": ["Kabir", "Ravidas", "Guru Nanak", "Tulsidas"], "answer": 3, "explanation": "Nirguna saints worshipped a formless God. Tulsidas was a Saguna saint devoted to Rama in human form.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-bhakti-sufi-41", "question": "The Adi Granth, the scripture of the Sikhs, was compiled in 1604 by:", "options": ["Guru Nanak", "Guru Arjan Dev", "Guru Gobind Singh", "Guru Angad"], "answer": 1, "explanation": "Guru Arjan Dev, the fifth Guru, compiled the Adi Granth in 1604 and installed it in the Harmandir Sahib. Guru Gobind Singh later added Guru Tegh Bahadur's hymns.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "history-bhakti-sufi-42", "question": "Who was the tenth and last human Guru of the Sikhs?", "options": ["Guru Tegh Bahadur", "Guru Har Krishan", "Guru Gobind Singh", "Guru Hargobind"], "answer": 2, "explanation": "Guru Gobind Singh (1666–1708) was the tenth Guru; after him the Granth itself became the Guru. Guru Tegh Bahadur, the ninth Guru, was his father.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-43", "question": "The tomb of the Chishti saint Shaikh Salim Chishti stands in the mosque complex at:", "options": ["Ajmer", "Delhi", "Fatehpur Sikri", "Lahore"], "answer": 2, "explanation": "Akbar built Fatehpur Sikri near the hermitage of Shaikh Salim Chishti, whose blessing he credited for the birth of Jahangir; the white marble tomb is in the Jama Masjid courtyard.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "history-bhakti-sufi-44", "question": "By occupation, the Bhakti saint Kabir is traditionally described as a:", "options": ["Weaver", "Cobbler", "Barber", "Tailor"], "answer": 0, "explanation": "Kabir was raised in a family of julahas (weavers) at Banaras. Ravidas was a leather worker, Sena a barber and Namdev a tailor.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-45", "question": "The Jnaneshwari, composed by the Marathi saint Jnaneshwar, is a commentary on:", "options": ["The Ramayana", "The Bhagavad Gita", "The Rig Veda", "The Bhagavata Purana"], "answer": 1, "explanation": "Jnaneshwar wrote the Jnaneshwari (Bhavartha Dipika) in Marathi around 1290 as a commentary on the Bhagavad Gita, making it available to people who knew no Sanskrit.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-46", "question": "The Marathi saint Ekanath is known for his Marathi rendering of:", "options": ["The Bhagavata Purana (its eleventh book)", "The Mahabharata", "The Gita Govinda", "The Upanishads"], "answer": 0, "explanation": "The 'Ekanathi Bhagavat' is Ekanath's Marathi commentary on the eleventh skandha of the Bhagavata Purana. He also edited the Jnaneshwari.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-47", "question": "Narsinh Mehta, whose bhajan 'Vaishnava jan to' was Gandhiji's favourite, was a saint-poet of:", "options": ["Maharashtra", "Rajasthan", "Gujarat", "Bengal"], "answer": 2, "explanation": "Narsinh Mehta (15th century) of Junagadh is regarded as the first great poet of Gujarati. 'Vaishnava jan to' describes the qualities of a true devotee.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-48", "question": "The town of Anandpur Sahib, where the Khalsa was later founded, was established in 1665 by:", "options": ["Guru Arjan Dev", "Guru Hargobind", "Guru Gobind Singh", "Guru Tegh Bahadur"], "answer": 3, "explanation": "Guru Tegh Bahadur founded Anandpur (first called Chak Nanaki) in 1665. Guru Gobind Singh founded the Khalsa there in 1699.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-49", "question": "Dadu Dayal, founder of the Dadu Panth and a Nirguna saint, preached mainly in:", "options": ["Rajasthan", "Assam", "Tamil Nadu", "Kashmir"], "answer": 0, "explanation": "Dadu Dayal (1544–1603) settled at Naraina near Jaipur; his followers, the Dadupanthis, are concentrated in Rajasthan.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-50", "question": "In the Sufi tradition, the relationship of 'pir' and 'murid' is that of:", "options": ["Ruler and subject", "Spiritual master and disciple", "Saint and his tomb", "Poet and patron"], "answer": 1, "explanation": "The pir (also shaikh or murshid) is the spiritual guide; the murid is the disciple who takes an oath of allegiance (bait) to him.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-51", "question": "Chaitanya Mahaprabhu was born in 1486 at:", "options": ["Puri", "Vrindavan", "Nabadwip", "Mathura"], "answer": 2, "explanation": "Chaitanya was born at Nabadwip (Navadvipa) in Bengal. He spent his last years at Puri, which makes Puri a tempting wrong answer.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-52", "question": "In 1708, before his death, Guru Gobind Singh declared which of the following to be the eternal Guru of the Sikhs?", "options": ["The Khalsa Panth alone", "The Guru Granth Sahib", "The Akal Takht", "The Dasam Granth"], "answer": 1, "explanation": "Guru Gobind Singh ended the line of human Gurus and vested the Guruship in the Granth (and the community, the Panth); the scripture is therefore called Guru Granth Sahib.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-53", "question": "Purandaradasa, honoured as the 'Pitamaha' (father) of Carnatic music, belonged to the:", "options": ["Virashaiva movement", "Haridasa movement of Karnataka", "Alvar tradition", "Varkari tradition"], "answer": 1, "explanation": "Purandaradasa (1484–1564) was a leading Haridasa, the Vaishnava devotional movement of Karnataka. He framed the graded lessons still used to teach Carnatic music.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-54", "question": "The Japji Sahib, the morning prayer that opens the Guru Granth Sahib, was composed by:", "options": ["Guru Nanak", "Guru Angad", "Guru Arjan Dev", "Guru Gobind Singh"], "answer": 0, "explanation": "Japji Sahib is Guru Nanak's composition and begins with the Mul Mantar. Guru Gobind Singh's Jaap Sahib is a different prayer.", "difficulty": "moderate", "source": "RRB NTPC · SSC CHSL"},
  {"id": "history-bhakti-sufi-55", "question": "Andal, the only woman among the twelve Alvars, composed:", "options": ["The Tiruvachakam", "The Tiruppavai", "The Tevaram", "The Periya Puranam"], "answer": 1, "explanation": "Andal's Tiruppavai (30 verses) and Nachiyar Tirumozhi are addressed to Vishnu. The Tiruvachakam is by Manikkavasagar, the Tevaram is the Nayanars' hymns and the Periya Puranam is by Sekkizhar.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-56", "question": "The hymns of the Alvars were compiled as the Nalayira Divya Prabandham in the 10th century by:", "options": ["Ramanuja", "Nathamuni", "Sekkizhar", "Nambi Andar Nambi"], "answer": 1, "explanation": "Nathamuni collected the 4,000 verses of the Alvars. Nambi Andar Nambi compiled the Shaiva Tirumurai, and Sekkizhar wrote the Periya Puranam.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-57", "question": "The Tiruvachakam, a classic of Tamil Shaiva devotion, was composed by:", "options": ["Appar", "Sundarar", "Manikkavasagar", "Nammalvar"], "answer": 2, "explanation": "Manikkavasagar wrote the Tiruvachakam; he is not counted among the 63 Nayanars but is revered alongside them. Nammalvar was an Alvar (Vishnu devotee).", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-58", "question": "Majma-ul-Bahrain ('The Mingling of the Two Oceans'), a work comparing Sufi and Vedantic ideas, was written by:", "options": ["Abul Fazl", "Amir Khusrau", "Dara Shikoh", "Faizi"], "answer": 2, "explanation": "Mughal prince Dara Shikoh, a follower of the Qadiri order, wrote Majma-ul-Bahrain (1655) and also had the Upanishads translated into Persian as Sirr-i-Akbar.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-59", "question": "The Rishi order, a Sufi tradition rooted in Kashmir, was founded by:", "options": ["Shaikh Nuruddin Wali (Nund Rishi)", "Mir Sayyid Ali Hamadani", "Shah-i-Hamadan's son Mir Muhammad", "Baba Farid"], "answer": 0, "explanation": "Nuruddin Wali (Nund Rishi, 1377–1438), a younger contemporary of Lal Ded, founded the Rishi order. Mir Sayyid Ali Hamadani brought the Kubrawi order to Kashmir.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-60", "question": "Surdas, the blind poet of the Sursagar, is traditionally regarded as a disciple of:", "options": ["Ramananda", "Vallabhacharya", "Chaitanya", "Nimbarka"], "answer": 1, "explanation": "Surdas belonged to Vallabhacharya's Pushti Marga and was one of the Ashtachhap poets. He is not counted among Ramananda's disciples.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-61", "question": "The philosophy of Chaitanya Mahaprabhu and the Gaudiya Vaishnavas is known as:", "options": ["Achintya Bhedabheda", "Shuddhadvaita", "Dvaitadvaita", "Vishishtadvaita"], "answer": 0, "explanation": "Achintya Bhedabheda means 'inconceivable difference and non-difference' between God and the soul. Shuddhadvaita is Vallabha's, Dvaitadvaita Nimbarka's and Vishishtadvaita Ramanuja's.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-62", "question": "Fawaid-ul-Fuad, a record of the conversations of Nizamuddin Auliya, was compiled by:", "options": ["Amir Khusrau", "Amir Hasan Sijzi", "Ziauddin Barani", "Nasiruddin Chiragh-i-Dehli"], "answer": 1, "explanation": "Amir Hasan Sijzi, a poet and disciple, recorded the saint's sayings in Fawaid-ul-Fuad, a classic of the malfuzat genre. Nasiruddin Chiragh-i-Dehli was Nizamuddin's spiritual successor.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-63", "question": "The scribe who wrote out the Adi Granth for Guru Arjan Dev in 1604 was:", "options": ["Bhai Mardana", "Baba Buddha", "Bhai Gurdas", "Bhai Mani Singh"], "answer": 2, "explanation": "Bhai Gurdas wrote the original volume at Guru Arjan's dictation. Baba Buddha was its first granthi (custodian), Bhai Mardana was Guru Nanak's rabab player, and Bhai Mani Singh later wrote out the Damdami version.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-64", "question": "The Akal Takht at Amritsar, the seat of temporal authority of the Sikhs, was established by:", "options": ["Guru Arjan Dev", "Guru Hargobind", "Guru Har Rai", "Guru Gobind Singh"], "answer": 1, "explanation": "Guru Hargobind built the Akal Takht in 1606 after his father's execution, wore two swords (miri and piri) and began to arm the community.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-bhakti-sufi-65", "question": "The Anubhava Mantapa, a hall for open spiritual discussion among men and women of all castes, was associated with:", "options": ["Ramanuja at Srirangam", "Basavanna at Kalyana", "Madhvacharya at Udupi", "Tukaram at Dehu"], "answer": 1, "explanation": "Basavanna set up the Anubhava Mantapa at Kalyana (Basavakalyan) in the 12th century; the Lingayat vachana poets, including Akka Mahadevi and Allama Prabhu, took part.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-66", "question": "Mirabai was married into the royal family of:", "options": ["Amber", "Marwar", "Mewar", "Bundi"], "answer": 2, "explanation": "Mirabai, a Rathore princess of Merta (Marwar), was married to Bhoj Raj, son of Rana Sanga of Mewar. She later left the court to live as a devotee of Krishna.", "difficulty": "hard", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-67", "question": "Samarth Ramdas, author of the Dasbodh, is traditionally regarded as the spiritual guide of:", "options": ["Shivaji", "Shahu", "Baji Rao I", "Ranjit Singh"], "answer": 0, "explanation": "Samarth Ramdas (1608–81), a devotee of Rama and Hanuman, is linked by tradition with Shivaji. The Dasbodh is his Marathi work of spiritual and practical advice.", "difficulty": "hard", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-68", "question": "Match the Sufi order with the saint who established it in India: A. Chishti B. Suhrawardi C. Naqshbandi D. Firdausi — 1. Khwaja Baqi Billah 2. Bahauddin Zakariya 3. Moinuddin Chishti 4. Badruddin Samarqandi", "options": ["A-3, B-1, C-2, D-4", "A-3, B-2, C-1, D-4", "A-2, B-3, C-1, D-4", "A-3, B-2, C-4, D-1"], "answer": 1, "explanation": "Moinuddin Chishti (Ajmer) – Chishti; Bahauddin Zakariya (Multan) – Suhrawardi; Khwaja Baqi Billah (Delhi, Akbar's time) – Naqshbandi; Badruddin Samarqandi – Firdausi, later spread in Bihar by Sharafuddin Yahya Maneri.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-69", "question": "Arrange these Sikh Gurus in the order of their Guruship: 1. Guru Har Rai 2. Guru Hargobind 3. Guru Ram Das 4. Guru Har Krishan", "options": ["3-1-2-4", "2-3-1-4", "3-2-4-1", "3-2-1-4"], "answer": 3, "explanation": "Ram Das was the fourth Guru, Hargobind the sixth, Har Rai the seventh and Har Krishan, the child Guru, the eighth.", "difficulty": "very-hard", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-70", "question": "Match the work with its author: A. Padmavat B. Kirtan Ghosha C. Vinaya Patrika D. Bhaktamal — 1. Tulsidas 2. Nabhadas 3. Malik Muhammad Jayasi 4. Sankaradeva", "options": ["A-3, B-4, C-1, D-2", "A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-3, B-1, C-4, D-2"], "answer": 0, "explanation": "Padmavat (1540) is the Sufi poet Jayasi's Awadhi romance; Kirtan Ghosha is Sankaradeva's Assamese verse; Vinaya Patrika is by Tulsidas; Nabhadas's Bhaktamal gives lives of the Bhakti saints.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-71", "question": "How many of these statements about Chaitanya Mahaprabhu are correct? I. He spent his last years at Puri. II. His Gaudiya followers regard him as Radha and Krishna in one form. III. He composed the Sursagar. IV. He was a disciple of Ramananda.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II are correct. The Sursagar is Surdas's work, and Chaitanya's initiation came from Ishvara Puri and Keshava Bharati, not Ramananda. So only two.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-72", "question": "How many of these statements about Sufi practice are correct? I. The urs marks the death anniversary of a saint, seen as his union with God. II. The murid is the spiritual master of a khanqah. III. A silsila is the chain of spiritual descent from master to disciple. IV. Qawwali grew out of the sama gatherings of the Chishtis.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, III and IV are correct. The murid is the disciple; the master is the pir or shaikh.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-73", "question": "Assertion (A): Tulsidas is counted among the Saguna Bhakti poets. Reason (R): He worshipped Rama as a personal God with form and attributes.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: Saguna bhakti is devotion to God with attributes (Rama, Krishna), as opposed to Nirguna bhakti to a formless God (Kabir, Nanak).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-74", "question": "Assertion (A): Nizamuddin Auliya's khanqah in Delhi drew people of every class and community. Reason (R): Nizamuddin Auliya held high office at the court of the Delhi Sultans.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 2, "explanation": "A is true. R is false: like other Chishtis, Nizamuddin kept away from the court and refused royal service; his open kitchen and sama drew people from all walks of life.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-75", "question": "Assertion (A): The Naqshbandi order insisted on strict observance of the sharia. Reason (R): Shaikh Ahmad Sirhindi belonged to the Naqshbandi order.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 1, "explanation": "Both are true, but R does not explain A. The order's orthodoxy predates Sirhindi; he was simply its most prominent Indian member in Akbar's and Jahangir's time.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-76", "question": "Which pair of saint and traditional occupation is NOT correctly matched?", "options": ["Kabir — weaver", "Ravidas — leather worker", "Namdev — tailor", "Sena — weaver"], "answer": 3, "explanation": "Sena, whose hymn is in the Guru Granth Sahib, was a barber. The other three pairs are the traditional accounts.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-77", "question": "How many of the following were Nayanars (Shiva devotees)? Appar, Sundarar, Nammalvar, Periyalvar", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Appar and Sundarar were Nayanars (with Sambandar, the authors of the Tevaram). Nammalvar and Periyalvar (Andal's foster-father) were Alvars, devotees of Vishnu.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-78", "question": "Arrange these teachers in chronological order: 1. Ramanuja 2. Basavanna 3. Shankaracharya 4. Madhvacharya", "options": ["3-2-1-4", "3-1-2-4", "1-3-2-4", "3-1-4-2"], "answer": 1, "explanation": "Shankaracharya – 8th century; Ramanuja – 11th–12th century (traditionally 1017–1137); Basavanna – 12th century; Madhvacharya – 13th century (1238–1317).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-79", "question": "Arrange these saints in chronological order: 1. Tukaram 2. Basavanna 3. Ekanath 4. Jnaneshwar", "options": ["2-4-3-1", "4-2-3-1", "2-3-4-1", "2-4-1-3"], "answer": 0, "explanation": "Basavanna – 12th century; Jnaneshwar – late 13th century; Ekanath – 16th century; Tukaram – 17th century, a contemporary of Shivaji.", "difficulty": "very-hard", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-80", "question": "Which pair of Sikh Guru and contribution is NOT correctly matched?", "options": ["Guru Angad — Gurmukhi script", "Guru Amar Das — manji system of preaching districts", "Guru Arjan Dev — compilation of the Adi Granth", "Guru Hargobind — founding of the Khalsa"], "answer": 3, "explanation": "The Khalsa was founded by Guru Gobind Singh in 1699. Guru Hargobind's contributions were the Akal Takht and the doctrine of miri-piri.", "difficulty": "very-hard", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-81", "question": "How many of these statements about the Lingayats (Virashaivas) are correct? I. They worship Shiva in the form of a linga. II. They traditionally bury their dead instead of cremating them. III. They encouraged child marriage. IV. They approved of the remarriage of widows.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. The Lingayats encouraged post-puberty marriage and widow remarriage, the opposite of the Dharmashastra norms of their time.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-82", "question": "Assertion (A): Guru Gobind Singh compiled the Adi Granth in 1604. Reason (R): Guru Gobind Singh added the hymns of Guru Tegh Bahadur to the Granth.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 3, "explanation": "A is false: Guru Arjan Dev compiled the Adi Granth in 1604. R is true: Guru Gobind Singh added his father's hymns, producing the version known as the Damdami Bir.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-83", "question": "How many of these statements are correct? I. Surdas composed his verses in Braj bhasha. II. Tulsidas was a contemporary of Akbar. III. Jayasi wrote the Padmavat in Awadhi. IV. Raskhan, a Muslim poet, wrote devotional verse on Krishna.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Tulsidas (1532–1623) lived through Akbar's reign; Jayasi's Padmavat (1540) is in Awadhi; Raskhan's Krishna poetry is in Braj.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-84", "question": "Match the Sufi term with its meaning: A. Wali B. Barakat C. Zikr D. Ziyarat — 1. Spiritual grace or power 2. Pilgrimage to a saint's tomb 3. A friend of God, a saint 4. Remembrance of God by repeating His names", "options": ["A-3, B-4, C-1, D-2", "A-1, B-3, C-4, D-2", "A-3, B-1, C-2, D-4", "A-3, B-1, C-4, D-2"], "answer": 3, "explanation": "Wali – friend of God (plural auliya); barakat – grace believed to flow from the saint; zikr – repetition of God's names; ziyarat – visiting a dargah for blessings.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-85", "question": "Which one of the following saints did NOT belong to the Varkari tradition of Pandharpur?", "options": ["Tukaram", "Namdev", "Ekanath", "Chaitanya"], "answer": 3, "explanation": "Tukaram, Namdev and Ekanath were Varkari saints devoted to Vitthala (Vithoba) of Pandharpur. Chaitanya founded the Gaudiya Vaishnava tradition of Bengal.", "difficulty": "very-hard", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-86", "question": "Vidyapati composed his famous devotional and love songs (padavali) on Radha and Krishna in:", "options": ["Braj Bhasha", "Awadhi", "Maithili", "Bhojpuri"], "answer": 2, "explanation": "Vidyapati (14th–15th century) wrote in Maithili, and his songs deeply influenced Chaitanya's movement in Bengal. Surdas wrote in Braj and Tulsidas in Awadhi.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-87", "question": "Which Sufi saint of Delhi is popularly called “Mehboob-e-Ilahi” (Beloved of God)?", "options": ["Nizamuddin Auliya", "Moinuddin Chishti", "Baba Farid", "Shaikh Salim Chishti"], "answer": 0, "explanation": "Nizamuddin Auliya (d. 1325), whose dargah is in Delhi, is called Mehboob-e-Ilahi. Moinuddin Chishti is known as Gharib Nawaz.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-bhakti-sufi-88", "question": "The short prose-poems of Basavanna and other Virashaiva saints are called:", "options": ["Abhangas", "Vachanas", "Dohas", "Pasurams"], "answer": 1, "explanation": "Vachanas are Kannada sayings of the Lingayat saints. Abhangas are Marathi Varkari songs, dohas Hindi couplets and pasurams the Tamil hymns of the Alvars.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-89", "question": "According to Sikh tradition, the foundation stone of the Harmandir Sahib at Amritsar was laid in Guru Arjan Dev's time by the Sufi saint:", "options": ["Baba Farid", "Shaikh Ahmad Sirhindi", "Bulleh Shah", "Mian Mir"], "answer": 3, "explanation": "Tradition holds that Mian Mir of Lahore, a Qadiri Sufi, laid the foundation stone in 1588 at Guru Arjan's invitation, symbolising openness to all.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-90", "question": "Vallabhacharya's philosophy, which underlies the Pushti Marga, is called:", "options": ["Vishishtadvaita", "Shuddhadvaita", "Dvaita", "Achintya Bhedabheda"], "answer": 1, "explanation": "Vallabha taught Shuddhadvaita (pure non-dualism). Vishishtadvaita is Ramanuja's, Dvaita Madhva's and Achintya Bhedabheda Chaitanya's.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-91", "question": "The Borgeet, devotional songs still sung in Assam's sattras and namghars, were composed by:", "options": ["Sankaradeva and Madhavadeva", "Chaitanya and Nityananda", "Jayadeva and Vidyapati", "Lalan Fakir and Hason Raja"], "answer": 0, "explanation": "Sankaradeva and his chief disciple Madhavadeva composed the Borgeet in Brajavali. Lalan Fakir was a 19th-century Baul of Bengal.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-92", "question": "Kabir is traditionally believed to have died at:", "options": ["Varanasi", "Prayag", "Maghar", "Ayodhya"], "answer": 2, "explanation": "Kabir chose to die at Maghar, near Gorakhpur, to defy the belief that dying in Kashi brings salvation while dying at Maghar does not.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-93", "question": "The dargah of Khwaja Qutbuddin Bakhtiyar Kaki, successor of Moinuddin Chishti, is at:", "options": ["Ajmer", "Pakpattan", "Gulbarga", "Mehrauli, Delhi"], "answer": 3, "explanation": "Bakhtiyar Kaki (d. 1235) lived in Delhi during Iltutmish's reign and is buried at Mehrauli. Baba Farid's shrine is at Pakpattan.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-bhakti-sufi-94", "question": "Which Sikh Guru became Guru at the age of about five, the youngest ever?", "options": ["Guru Har Rai", "Guru Har Krishan", "Guru Hargobind", "Guru Gobind Singh"], "answer": 1, "explanation": "Guru Har Krishan succeeded Guru Har Rai in 1661 as a child and died of smallpox in Delhi in 1664; Gurdwara Bangla Sahib is associated with him.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-bhakti-sufi-95", "question": "Shaikh Muhammad Ghaus of Gwalior, near whose tomb Tansen lies buried, belonged to which Sufi order?", "options": ["Chishti", "Suhrawardi", "Naqshbandi", "Shattari"], "answer": 3, "explanation": "Muhammad Ghaus was a leading Shattari saint, respected by Humayun. Tansen's tomb stands in the garden of his mausoleum at Gwalior.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-96", "question": "The manji system, which divided the Sikh community into units for preaching and organisation, was introduced by:", "options": ["Guru Angad", "Guru Amar Das", "Guru Arjan Dev", "Guru Hargobind"], "answer": 1, "explanation": "Guru Amar Das set up 22 manjis and strengthened the langar at Goindwal. Guru Angad is credited with the Gurmukhi script.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-97", "question": "The Dasam Granth is a collection of compositions attributed to:", "options": ["Guru Nanak", "Guru Tegh Bahadur", "Guru Gobind Singh", "Guru Arjan Dev"], "answer": 2, "explanation": "The Dasam Granth (“Book of the Tenth”) contains works attributed to Guru Gobind Singh, such as the Jaap Sahib. It is distinct from the Guru Granth Sahib.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-98", "question": "The Nath Panthi yogis, who influenced Kabir and other Nirguna saints, trace their tradition to Matsyendranath and:", "options": ["Gorakhnath", "Namdev", "Ramananda", "Dadu Dayal"], "answer": 0, "explanation": "The Naths, followers of Gorakhnath, rejected caste and ritual and practised hatha yoga; their vocabulary appears in Kabir's poetry.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-99", "question": "Janabai, a woman saint of the Varkari tradition whose abhangas are still sung, lived as a servant in the household of:", "options": ["Tukaram", "Namdev", "Eknath", "Jnaneshwar"], "answer": 1, "explanation": "Janabai was a maid in Namdev's family at Pandharpur and became one of the best-known women Varkari poets.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-100", "question": "Kanakadasa, a Haridasa saint of Karnataka from the shepherd (Kuruba) community, is linked by legend to a window at the Krishna temple in:", "options": ["Udupi", "Hampi", "Sringeri", "Melukote"], "answer": 0, "explanation": "The “Kanakana Kindi” at Udupi marks the spot where, by legend, the idol turned to give darshan to Kanakadasa, who was denied entry.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-101", "question": "Which Chishti saint, successor of Nizamuddin Auliya, was called “Chirag-i-Dehli” (Lamp of Delhi)?", "options": ["Amir Khusrau", "Bande Nawaz Gesudaraz", "Shaikh Nasiruddin Mahmud", "Shaikh Salim Chishti"], "answer": 2, "explanation": "Nasiruddin Mahmud (d. 1356) led the Chishtis in Delhi after Nizamuddin. His disciple Gesudaraz took the order to Gulbarga in the Deccan.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-102", "question": "According to tradition, Tansen learned music from the saint-musician Swami Haridas, who lived at:", "options": ["Pandharpur", "Puri", "Vrindavan", "Ayodhya"], "answer": 2, "explanation": "Swami Haridas, a Krishna devotee and dhrupad master, lived at Vrindavan. Legend says Akbar went in disguise with Tansen to hear him.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-103", "question": "Dhanna, whose hymns appear in the Guru Granth Sahib, was a Bhakti saint from a family of:", "options": ["Weavers in Varanasi", "Jat peasants in Rajasthan", "Tailors in Maharashtra", "Barbers in Punjab"], "answer": 1, "explanation": "Dhanna was a Jat farmer from Rajasthan, traditionally a disciple of Ramananda. Kabir was a weaver, Namdev a tailor and Sena a barber.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-104", "question": "Munis-ul-Arwah, a biography of Khwaja Moinuddin Chishti, was written by the Mughal princess:", "options": ["Gulbadan Begum", "Jahanara Begum", "Zeb-un-Nisa", "Roshanara Begum"], "answer": 1, "explanation": "Jahanara, Shah Jahan's daughter and a Qadiri disciple, wrote Munis-ul-Arwah. Gulbadan wrote the Humayun-nama; Zeb-un-Nisa was a poet.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-105", "question": "Match the Telugu saint-poet with the contribution: A. Annamacharya B. Bammera Potana C. Bhadrachala Ramadasu D. Tyagaraja — 1. Telugu rendering of the Bhagavata Purana 2. Thousands of kirtanas to Venkateswara of Tirupati 3. Built the Rama temple at Bhadrachalam 4. The Pancharatna kritis", "options": ["A-2, B-1, C-3, D-4", "A-1, B-2, C-3, D-4", "A-2, B-3, C-1, D-4", "A-2, B-1, C-4, D-3"], "answer": 0, "explanation": "Annamacharya sang of Venkateswara, Potana wrote the Andhra Maha Bhagavatamu, Ramadasu (Kancherla Gopanna) built the Bhadrachalam temple, and Tyagaraja composed the Pancharatna kritis.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-bhakti-sufi-106", "question": "Match the Sufi or mystic poet with the work or form: A. Waris Shah B. Lal Ded C. Bulleh Shah D. Shah Abdul Latif Bhittai — 1. Kafis in Punjabi 2. Shah Jo Risalo in Sindhi 3. Heer, a Punjabi verse romance 4. Vakhs in Kashmiri", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2"], "answer": 3, "explanation": "Waris Shah wrote Heer, Lal Ded spoke vakhs, Bulleh Shah of Kasur sang kafis, and Shah Abdul Latif's verse is collected in Shah Jo Risalo.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-107", "question": "Consider the following statements: 1. Jagannath Dasa rendered the Bhagavata Purana into Odia. 2. Sankaradeva rendered parts of the Bhagavata Purana into Assamese. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Regional Bhagavatas, like Potana's in Telugu and Ekanath's in Marathi, carried Krishna bhakti in people's languages.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-108", "question": "Arrange these Chishti saints in the order of spiritual succession: 1. Nizamuddin Auliya 2. Baba Farid 3. Nasiruddin Chirag-i-Dehli 4. Qutbuddin Bakhtiyar Kaki", "options": ["2, 4, 1, 3", "4, 1, 2, 3", "4, 2, 3, 1", "4, 2, 1, 3"], "answer": 3, "explanation": "Moinuddin Chishti was followed by Bakhtiyar Kaki, then Baba Farid of Pakpattan, then Nizamuddin Auliya, then Nasiruddin Chirag-i-Dehli.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-109", "question": "Assertion (A): Kabir rejected both idol worship and ritual prayer. Reason (R): Kabir was a Nirguna bhakta who saw God as formless and present within every being.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: since God has no form and dwells within, Kabir saw no need for images, pilgrimages or set rituals of either faith.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-110", "question": "How many of these statements about Sankaradeva are correct? I. He founded the Ekasarana Dharma. II. He created the one-act Ankiya Naat plays. III. He set up namghars as village prayer halls. IV. He was a contemporary of Chaitanya Mahaprabhu.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Sankaradeva (1449–1568) outlived Chaitanya (1486–1534), and his Ankiya Naat performances are known as Bhaona.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-111", "question": "Consider the following statements: 1. Mian Mir of Lahore belonged to the Qadiri order. 2. Dara Shikoh followed the Qadiri order as a disciple of Mulla Shah Badakhshi, Mian Mir's successor. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. The Qadiri order, named after Abdul Qadir Jilani of Baghdad, won the devotion of Dara Shikoh and Jahanara.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-112", "question": "Consider the following statements: 1. The Qalandars and Madaris were “be-sharia” Sufis who did not bind themselves to the sharia. 2. The Chishti and Suhrawardi orders were “ba-sharia” orders. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Ba-sharia orders accepted Islamic law; wandering be-sharia groups such as the Qalandars often ignored ritual rules.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-113", "question": "Arrange these saints in chronological order: 1. Tukaram 2. Andal 3. Sankaradeva 4. Basavanna", "options": ["2, 4, 3, 1", "4, 2, 3, 1", "2, 3, 4, 1", "2, 4, 1, 3"], "answer": 0, "explanation": "Andal (8th century), Basavanna (12th century), Sankaradeva (15th–16th century) and Tukaram (17th century).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-114", "question": "Assertion (A): Chokhamela's abhangas voice the pain of being kept outside the Vitthala temple at Pandharpur. Reason (R): Chokhamela belonged to the Mahar community, then treated as untouchable.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Chokhamela (14th century), a Varkari saint, was denied temple entry because of caste; his samadhi stands at the temple steps.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-bhakti-sufi-115", "question": "Match the teacher with the centre associated with him: A. Madhvacharya B. Ramanuja C. Shankaracharya D. Vallabhacharya — 1. Nathdwara (Shrinathji) 2. Udupi 3. Srirangam 4. Sringeri", "options": ["A-3, B-2, C-4, D-1", "A-2, B-3, C-1, D-4", "A-2, B-3, C-4, D-1", "A-2, B-4, C-3, D-1"], "answer": 2, "explanation": "Madhva founded the Krishna temple tradition at Udupi, Ramanuja led the Srirangam temple, Shankara set up a matha at Sringeri, and the Pushti Marga's chief shrine of Shrinathji is at Nathdwara.", "difficulty": "very-hard", "source": "UPSC Prelims"},
];

